skin.css:
/*
  TailwindJCINK - Minimal Base Stylesheet

  This is intentionally minimal. Tailwind CSS handles most styling via the CDN.
  Add custom CSS here only for JCINK-specific overrides.
*/

/* CSS Variables for theme colors */
:root {
  --forum-bg: #f1f5f9;
  --forum-surface: #ffffff;
  --forum-border: #e2e8f0;
  --forum-text: #1e293b;
  --forum-muted: #64748b;
  --forum-accent: #0ea5e9;
}

/* Dark mode variables */
.dark {
  --forum-bg: #0f172a;
  --forum-surface: #1e293b;
  --forum-border: #334155;
  --forum-text: #f1f5f9;
  --forum-muted: #94a3b8;
  --forum-accent: #38bdf8;
}
